def girth_ok(edges):
    adj=[set() for _ in range(n)]
    for u,v in edges:
        adj[u].add(v); adj[v].add(u)
    # check cycles <=6: for each edge, shortest path without edge >=6? if path length <=5 => cycle <=6
    for u,v in edges:
        # BFS from u to v ignoring edge up to depth5
        q=[(u,0)]; seen={u}
        while q:
            x,d=q.pop(0)
            if d>=5: continue
            for y in adj[x]:
                if (x==u and y==v) or (x==v and y==u):
                    continue
                if x==u and y==v: continue
                if (x==u and y==v) or (x==v and y==u): continue
                # need ignore actual edge, both dirs
                if (x==u and y==v) or (x==v and y==u): continue
                if y==v:
                    return False
                if y not in seen:
