def compute_girth(edges):
    adj=[[] for _ in range(n)]
    for u,v in edges:
        adj[u].append(v); adj[v].append(u)
    g=999
    for s in range(n):
        dist=[-1]*n; par=[-1]*n
        dist[s]=0; q=collections.deque([s])
        while q:
            u=q.popleft()
            for v in adj[u]:
                if dist[v]<0:
                    dist[v]=dist[u]+1; par[v]=u; q.append(v)
                elif par[u]!=v and par[v]!=u:
                    g=min(g, dist[u]+dist[v]+1)
    return g if g<999 else None

def colorable3(edges):
    adj=[set() for _ in range(n)]
    for u,v in edges: adj[u].add(v); adj[v].add(u)
    order=sorted(range(n), key=lambda x:-len(adj[x]))
    col=[-1]*n
    def bt(k):
        if k==n: return True
        u=order[k]
        used={col[v] for v in adj[u] if col[v]!=-1}
        for c in range(3):
            if c not in used:
                col[u]=c
                if bt(k+1): return True
                col[u]=-1
        return False
    return bt(0)

