n=14

def canonical_cycle(cyc):
    # cyc list length k cyclic vertices; canonical among rotations and reversal
    k=len(cyc)
    seqs=[]
    for s in (cyc, list(reversed(cyc))):
        for i in range(k):
            seqs.append(tuple(s[i:]+s[:i]))
    return min(seqs)

def find_for_sizes(sizes):
    colors=[]
    for c,sz in enumerate(sizes): colors += [c]*sz
    cand=[]
    for i in range(n):
        for j in range(i+1,n):
            if colors[i]!=colors[j]: cand.append((i,j))
    cand_set=set(cand)
    var={e:z3.Bool('e_%d_%d'%e) for e in cand}
    cycles=set()
    # enumerate simple cycles in complete allowed graph by permutations/combinations up to 6
    verts=range(n)
    adj_allowed=[[False]*n for _ in range(n)]
    for u,v in cand:
        adj_allowed[u][v]=adj_allowed[v][u]=True
    # DFS cycles starting min vertex to avoid too many
    for start in range(n):
        def dfs(path):
            cur=path[-1]
            if len(path)>=3 and len(path)<=6 and adj_allowed[cur][start]:
                cycles.add(canonical_cycle(path[:]))
            if len(path)==6: return
            for nb in range(start+1,n): # ensure start min of cycle; vertices > start
                if nb not in path and adj_allowed[cur][nb]:
                    dfs(path+[nb])
        for nb in range(start+1,n):
            if adj_allowed[start][nb]: dfs([start,nb])
    print('sizes',sizes,'cand',len(cand),'cycles',len(cycles))
    sol=z3.Solver()
    for cyc in cycles:
        es=[]
        k=len(cyc)
        for i in range(k):
            u,v=cyc[i],cyc[(i+1)%k]
            if u>v: u,v=v,u
            es.append(var[(u,v)])
        sol.add(z3.Not(z3.And(es)))
    sol.add(z3.PbGe([(var[e],1) for e in cand],18))
    sol.set('timeout',10000)
    r=sol.check()
    print('check',r)
    if r==z3.sat:
        m=sol.model()
        edges=[e for e in cand if z3.is_true(m.eval(var[e], model_completion=True))]
        print('edges',len(edges), edges)
        return edges
    return None

