from pysat.formula import IDPool
n=14

def canonical_cycle(cyc):
    k=len(cyc); best=None
    r=list(reversed(cyc))
    for s in (cyc,r):
        for i in range(k):
            t=tuple(s[i:]+s[:i])
            if best is None or t<best: best=t
    return best

def solve_part(sizes):
    colors=[]
    for c,sz in enumerate(sizes): colors += [c]*sz
    cand=[]; edge_var={}
    vpool=IDPool()
    for i in range(n):
      for j in range(i+1,n):
        if colors[i]!=colors[j]:
          e=(i,j); edge_var[e]=vpool.id(e); cand.append(e)
    adj=[[False]*n for _ in range(n)]
    for u,v in cand: adj[u][v]=adj[v][u]=True
    clauses=[]; cycles=set()
    for start in range(n):
        def dfs(path):
            cur=path[-1]
            L=len(path)
            if L>=3 and L<=6 and adj[cur][start]:
                cycles.add(canonical_cycle(path[:]))
            if L==6: return
            # all vertices > start to make start min
            for nb in range(start+1,n):
                if nb not in path and adj[cur][nb]:
                    dfs(path+[nb])
        for nb in range(start+1,n):
            if adj[start][nb]: dfs([start,nb])
    for cyc in cycles:
        cl=[]; k=len(cyc)
        for i in range(k):
            u,v=cyc[i],cyc[(i+1)%k]
            if u>v: u,v=v,u
            cl.append(-edge_var[(u,v)])
        clauses.append(cl)
    card=CardEnc.atleast(lits=[edge_var[e] for e in cand], bound=18, vpool=vpool, encoding=EncType.totalizer)
    clauses.extend(card.clauses)
    print('sizes',sizes,'cand',len(cand),'cycles',len(cycles),'clauses',len(clauses), flush=True)
    with Glucose3(bootstrap_with=clauses) as s:
        res=s.solve()
        print('res',res, flush=True)
        if res:
            model=set(l for l in s.get_model() if l>0)
            edges=[e for e in cand if edge_var[e] in model]
            return edges
    return None
